def count_valid_interval_sequences(n, m, x):
    mod = 1000000007
    if n == 1:
        return 1 if x <= m else 0

    ways = [0] * m
    for l, _ in enumerate(range(1, x)):
        ways[l] = ways[l-1]

    for r, _ in enumerate(range(x+1, m+1)):
        for l, w in enumerate(ways):
            t_l, t_r = l-1, r-1
            new_l, new_r = l-1, r-1
            is_present = True
            while t_r >= new_l and t_l >= new_r:
                while t_l >= new_l and t_r >= new_r:
                    new_r, new_l = t_r, t_l
                    is_present = False
                    break
                if not is_present:
                    break
                new_l, new_r = l-1, r-1
                for i in range(t_r-1, t_l-1, -1):
                    if l == i:
                        break
                    else:
                        ways[i] -= w
                        ways[i] = (ways[i] + mod) % mod
                t_r -= 1
                t_l -= 1

    return ways[-1]

