def min_difference(a, l, r, k):
    cnt = defaultdict(int)
    for i in range(l - 1, r):
        cnt[a[i]] += 1
        if len(cnt) > k:
            return float('inf')
    min_diff = float('inf')
    for i in range(1, max(cnt.keys()) + 1):
        groups = [0, 0]
        current = {}
        for j in range(l - 1, r):
            groups.append(cnt[a[j]])
            if j % k == 0:
                min_diff = min(min_diff, max(groups) - min(groups))
                current = defaultdict(int)
                current[j % k] += 1
        if len(current) > 1:
            min_diff = min(min_diff, groups[-1] - groups[0])
        min_diff = min(min_diff, max(groups) - 1)
        groups = [0, 0]
        for j in range(i + 1, r):
            groups.append(cnt[a[j]])
            if (j - i + 1) % k == 0:
                min_diff = min(min_diff, max(groups) - 1)
        min_diff = max(min_diff, groups[-1] - min(groups))
    return min_diff if min_diff != float('inf') else -1

