from heapq import heappush, heappop

def is_good_graph(G, removed_edges):
    visited = [False] * (len(G) + 1)
    pq = [(0, 1)]
    while pq:
        diff, u = heappop(pq)
        if u == len(G) and visited[u] and is_good_graph(G, removed_edges):
            return True
        if visited[u]:
            continue
        visited[u] = True
        for v in G[u]:
            if v < len(G) and not visited[v] and is_removed_edge(G, removed_edges, (u, v)):
                heappush(pq, (diff + 1, v))
            if v > u and not visited[v] and is_removed_edge(G, removed_edges, (v, u)):
                heappush(pq, (diff + 1, v))
    return visited[-1]

def is_removed_edge(G, removed_edges, edge):
