from collections import defaultdict, deque

def reconstruct_sequence(graph):
    visited = set()
    inversions = defaultdict(set)
    sorted_vertices = []

    for key, value in graph.items():
        for child in value:
            inversions[child].add(key)

    stack = sorted(list(graph.keys()))

    while stack:
        node = stack.pop()
        if not visited.add(node):
            sorted_vertices.append(node)
            if inversions[node]:
                for child in sorted(inversions[node], reverse=True):
                    stack.append(child)

    return sorted_vertices[::-1]

