from heapq import heapify, heappop, heappush

def find_min_sequence(N, M, edges):
    G = [[False for _ in range(N+1)] for _ in range(N+1)]
    labels = [0] * (N+1)

    for node1, node2 in edges:
        node2 += 1  # Adjustition for zero-based to one-based indexing
        G[node1-1][node2-1] = True  # Add edge as a directed edge

    result = [-1] * N
    heap = [[0, 0, 0]]  # Initial priority queue with a height of 0 at node-0

    while heap:
        height, node, label = heappop(heap)
        if node != 0 and height > labels[node-1]:
            continue  # Skip revisited nodes with higher label

        labels[node-1] = height

        if node == N:
            continue  # Reached the end node (node N)

        node += 1  # Adjust inclination for zero-based to one-based indexing

        if node <= N and G[node-1][node-1]:
            heappush(heap, [labels[node-1], node-1, label+1])  # Process subsequent node as new subsequence

        for other_node in range(N+1):
            if G[node-1][other_node]:
                if label == labels[other_node] and height != labels[other_node]:
                    continue  # Check both cases from previous and checking heights of another node.
                heappush(heap, [max(labels[node-1], labels[other_node]), other_node, label + 1])

    for i in range(N-1, 0, -1):
        if labels[i] != labels[i-1]:
            return [-1] * N  # No sequence possible to construct

    for i in range(N):
        result[N-i-1] = i + 1
    return result

