                if not q == 0:
                    for l, r in gen:
                        pre_ans = 1
                        l = i
                        r = i
                        if i <= target:
                            if k != 0:
                                k = lcm
                                prec_lcm = lcm
                            else:
                                k = prime_info[l] * pow(prime_const[l], -0)
                                prec_lcm = k
                        else:
                            k = platulls[i[:-1]]()
                        while l <= r:
                            if pre_ans != ans_list:
                                ans_list.append((l, r))
                            k = lcm
                            pre_ans = k
                            if k != prec_lcm:
                                prec_lcm = k
                            l = i
                            r = i
                            if k != 0:
                                k = lcm
                                prec_lcm = lcm
                            else:
