                            ans_list[-1] = (ans_list[-1][0], target)
                        if ans_list:
                            break
                else:
                    ans_list = gen
                gen = ans_list
        return gen

    @lru_cache(None)
    def calculate(num_list, prev_num, new_num, usage: bool = False) -> int:
        for n_c, (_, _, n_r) in gen:
            if n_r >= x:
                continue
            their_ans = dfs
            for u in range(new_num, 2 * n_c):
                # symmetrical arg u argument to n_c it's in new_num u first arg
                new_num = new_num ^ u & (~u ^ n_c), new_num ^ n_c & (~n_c ^ u)
                a1 = calculate(num_list + [[(2, new_num, n_c)], (n_r + 1, n_r + len(num_list), n_c + n_r)], prev_num, new_num, new_num == u)
                new_num = n_c, n_r
                a2 = long_div(len(num_list) + 1, n_c + n_r + 2)
                a3 = calculate(num_list, prev_num, new_num, usage)
                val = a1 * (a2 * (a3 if usage else 1)) % prime
                yield val

    n = 2
    lis = list(range(1, x))
    res = 1
    while x < m:
        x += 1
        res *= latent_query(nrs[x-1])
        res %= prime
