    horizontal_wires = []
    vertical_wires = []

    # Sort points by y-coordinate, then by x-coordinate
    sparks.sort(key=lambda p: (p[0], p[1]))

    for i in range(n):
        for j in range(i + 1, n):
            if sparks[i][1] == sparks[j][1]:
                x1, y1, x2, y2 = sparks[i]
                if sparks[j][1] < y1 or sparks[j][1] > y2:
                    continue
                if sparks[i][0] == x2:
                    horizontal_wires.append((y1, y2, x1, x2))
                elif sparks[i][0] == x1:
                    horizontal_wires.append((y2, y1, x2, x1))
                elif sparks[j][0] == x2:
                    horizontal_wires.append((y1, y2, x1, x2))
                elif sparks[j][0] == x1:
                    horizontal_wires.append((y2, y1, x2, x1))
            elif sparks[i][0] == sparks[j][0]:
                x1, y1, x2, y2 = sparks[i]
                if sparks[j][0] < x1 or sparks[j][0] > x2:
                    continue
                if sparks[j][1] == y1:
                    vertical_wires.append((x1, x2, y1, y2))
                elif sparks[j][1] == y2:
                    vertical_wires.append((x2, x1, y1, y2))
                elif sparks[j][0] == x1:
                    vertical_wires.append((x1, x2, y1, y2))
                elif sparks[j][0] == x2:
                    vertical_wires.append((x2, x1, y1, y2))

    return horizontal_wires, vertical_wires

