from typing import List, Tuple

def find_lexicographically_smallest_sequence(N: int, M: int, edges: List[Tuple[int, int]]) -> List[int] or int:
    """
    Finds the lexicographically smallest sequence A that can lead to the given graph G.
    If no such sequence exists, it returns -1.
    """
    # Build a graph from the input edges
    graph = {i: list() for i in range(N + 1)}

    for a, b, _ in edges:
        graph[a].append(b)

    # Helper function for topological sorting
    def dfs(node: int, visited: List[bool], stack: List[int]) -> None:
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, stack)
        stack.append(node)

    # Topological sorting from all vertices
    visited = [False] * (N + 1)
    stack = []
    for vertex in range(1, N + 1):
        if not visited[vertex]:
            dfs(vertex, visited, stack)

    # Reverse the stack to get BFS order, with degree 0 at the end
    stack.reverse()
    degree = {i: 0 for i in range(1, N + 1)}
    for vertex in stack:
        for neighbor in graph[vertex]:
            degree[neighbor] += 1

    # BFS from degree=0 vertices
    visited = [False] * (N + 1)
    queue = [i for i in range(1, N + 1) if degree[i] == 0]
    sequence = []

    while queue:
        vertex = queue.pop(0)
        sequence.append(vertex)
        visited[vertex] = True
        for neighbor in graph[vertex]:
            degree[neighbor] -= 1
            if degree[neighbor] == 0 and not visited[neighbor]:
                queue.append(neighbor)

    if len(sequence) == N:
        return "".join(map(str, sequence)), 0
    return -1

# Example usage
T = int(input())
for _ in range(T):
    N, M = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(M)]
    result = find_lexicographically_smallest_sequence(N, M, edges)
    print(result)
