        if d == 1:
            nr, nc = pos
            for i in range(1, min(nr-2, nc-2) + 1):
                if (nr, nc-i) in completed or (nr, nc-i) in total_hatched:
                    continue
                completed.add((nr, nc-i))
                if canvas[nr+i][nc] != '#':
                    start = (nr+i, nc)
                    total_seen.add((nr+i, nc))
                    break
            else:
                total_seen.add((nr, nc-2))

        elif d == -1:
            nr, nc = pos
            for i in range(1, min(nr+2, nc+2) + 1):
                if (nr, nc-i) in completed or (nr-i, nc) in total_hatched:
                    continue
                completed.add((nr-i, nc))
                if canvas[nr-i][nc] != '#':
                    end = (nr-i, nc)
                    total_seen.add((nr-i, nc))
                    break
            else:
                total_seen.add((nr, nc+1))

        if finished:
            left, top = min(total_seen), min(total_hatched)
            right, bot = max(total_seen), max(total_hatched)
            canvas = [['.' for _ in range(right-left+1)] for _ in range(bot-top+1)]
            for x, y in min(total_seen):
                canvas[y-left][x-left] = '#'
            for x, y in min(total_hatched):
                canvas[y-bot][x-right] = '#'
            return

