def check_edges(edges):
    edges.sort(key=lambda x: x[1])
    current_color = "WB"
    minimum_diameter = [float('inf')]
    for i in range(1, len(edges) + 1):
        if current_color == "WB":
            current_color = "BW"
            edges[0][0] = edges[1][0]
            cost = edges.pop(1)[1] - edges[0][0]
            minimum_diameter[0] = min(minimum_diameter[0], cost)
        else:
            current_color = "WB"
            edges[0][0] = edges[1][0]
            cost = edges.pop(1)[1] - edges[0][1]
            minimum_diameter[0] = min(minimum_diameter[0], cost)
    return minimum_diameter[0]

def solve(B, W):
    if B == 0 and W == 0:
        return -1
    if B == 1 and W == 1:
        return "WB"
    if B == W == 1:
        return "WB"
    if B > 1:
        B -= 1
    if W > 1:
        W -= 1
    edges = []
    for i in range(1, W + 1):
        edges.append([i, i-1])
    edges.append([W + 1, W])
    for i in range(B):
        edges.append([B + i + 1, W + 1])
    tree = create_tree(edges)
    return tree, check_edges(edges)

