import itertools

def beauty_of_permutation(permutation):
    beauty = 0
    for i in range(len(permutation)):
        for j in range(i, len(permutation)):
            if list(permutation[i:j+1]) == list(set(list(permutation[i:j+1]))):
                beauty += 1
    return beauty

def find_permutation(n, k):
    def dfs(start, path):
        if start == len(path):
            global beauty
            beauty = beauty_of_permutation(path)
            return path
        for i in range(len(path)):
            new_paths = path[:]
            new_paths[i:start] = path[start:start]
            if beauty == k:
                return path
            elif beauty > k:
                return []
            new_paths[start:start] = path[start:start]
            res = dfs(start + 1, new_paths)
            if res:
                return res
        return []

    global beauty
    if beauty_of_permutation([]) == k:
        return 'YES', []
    else:
        return 'NO'

def solve_queries(queries):
