            if not new_points or new_points[-1][0] != x:
                new_points.append((x, y))
            else:
                new_points[-1] = (new_points[-1][0], y)
        for x, y, next_x, next_y in points:
            if x != next_x:
                result.append(f"{x} {y} {min(x, next_x)} {y}")
        return result

    n = len(sparks)
    max_y, max_x = 0, 0
    for x, y in sparks:
        max_y = max(max_y, y)
        max_x = max(max_x, x)

    y_points = [i + max_y for i in range(n)]
    result = process_points(sparks + [(x, y_points[i]) for i, (x, y) in enumerate(sparks)])
    h = len(list(bisect_left(result, f"{x1} {y1} {x2} {y2}") for x1, y1, x2, y2 in result))
    v = len(list(bisect_left(result, f"{x} {y1} {x} {y2}") for y1, y2 in y_points))
