    right_index = left_index + 1
    mid = index * segment_size + query_index // 2
    if query_index == query_element:
        value_index = ((index * segment_size) + query_index // 2) + (query_element * segment_size)
        segment_tree[index][value_index] = value
    else:
        if segment_size > 1:
            if mid > query_index:
                segment_tree, value = process_query(segment_tree, left_index, value, segment_size // 2, query_index, query_element)
            else:
                segment_tree, value = process_query(segment_tree, right_index, value, segment_size // 2, query_index, query_element)
        if mid - segment_size // 2 >= query_index and query_index + segment_size // 2 <= mid:
            segment_tree, value = max_segment_tree(segment_tree, index, query_index, query_element, value)
    return segment_tree, value

def max_segment_tree(segment_tree, index, query_index, query_element, modified_value, is_query_fourth=True):
    l_index, r_index, left_child, right_child = index * 2, index * 2 + 1, "", ""
    if left_child in segment_tree and right_child in segment_tree:
        if left_child + right_child == query_index * 2 - 1 and is_query_fourth:
            segment_tree[left_child] += modified_value
            segment_tree[right_child] += modified_value
        elif left_child + right_child == query_index * 2 and is_query_fourth:
            segment_tree[left_child] = query_element
            segment_tree[right_child] = query_element
        else:
            if segment_tree[left_child] >= modified_value:
                right_child = left_child
            else:
                left_child == right_index
        segment_tree = max_segment_tree(segment_tree, index, query_index, query_element, modified_value, is_query_fourth)
    return segment_tree

