from math import factorial

MOD = 1000000007

def factorial_mod(n, mod):
    if n < 0:
        return -1
    elif n == 0:
        return 1
    else:
        return (n * factorial_mod(n - 1, mod)) % mod

def combinations(n, k, mod):
    return factorial_mod(n, mod) // (factorial_mod(n - k, mod) * factorial_mod(k, mod))

def count_intersections(n, m, x):
    if m < x or n < m:
        return 0
    else:
        return (factorial(n) * combinations(n, min(n, x) - 1, 0) * 3 * combinations(m, x) * (min(n, x) - 2) // 2) % MOD

