import collections
from typing import List

class Graph:
    def __init__(self):
        self.graph = collections.defaultdict(list)
        self.labels = collections.defaultdict(list)

    def add_edge(self, u, v, label):
        self.graph[u].append((v, label))
        self.labels[label].append((u, v))

    def topological_sort(self):
        sorted_nodes = []
        visited = [False] * (len(self.graph) + 1)

        def dfs(node):
            visited[node] = True
            for neighbor, label in self.graph[node]:
                if not visited[self.labels[label][0][1]]:
                    dfs(self.labels[label][0][1])
            sorted_nodes.append(node)

        for node in range(len(self.graph)):
            if not visited[node]:
                dfs(node)
        return sorted_nodes

class Solution:
    def constructA(self, graph: 'Graph') -> List[int]:
        edges = sorted(graph.topological_sort())
        n = len(edges)
        result = [-1] * n
        i = 0
        current = edges[0]

        while i < n:
            if len(edges) == 1 and current == edges[0]:
                return result
            if current in edges[i + 1:]:
                result[i] = current
                edges.remove(edges[i + 1:])
                i -= 1
            i += 1
            if len(edges) == 1:
                return result

        return result

