def is_beautiful(permutation, beauty):
    blocks = []
    current_block = []
    for i in range(len(permutation)):
        current_block.append(permutation[i])
        if i == len(permutation) - 1 or permutation[i] != permutation[i + 1] - 1:
            blocks.append((''.join(current_block), i // 2 + 1))
            current_block = []
    if blocks:
        return beauty == sum(len(block[0].split(',')) for block in blocks)
    return False

def find_permutation(n, beauty):
    permutations = []
    count = 1
    while len(permutations) < beauty:
        permutation_list = []
        for _ in range(n - count + 1):
            permutation_list.append(count)
            count += 1
        sum_ = 0
        while sum_ != beauty:
            to_remove = sum_ % (n + 1) - 1
            to_add = to_remove + count - (n + 1)
            permutation_list.extend([to_add, to_remove])
            sum_ += to_remove - to_add
            count = n + 1
        permutation_list.sort()
        permutations.append(permutation_list)
    return permutations

def solve(n, beauty):
    if not is_beautiful([i for i in range(1, n + 1)], beauty):
        return "NO"
    else:
        return "YES\n" + "\n".join(map(str, find_permutation(n, beauty)))

